    def backtrack(row: int) -> int:
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if col in columns or row - col in diagonal1 or row + col in diagonal2:
                continue
            columns.add(col)
            diagonal1.add(row - col)
            diagonal2.add(row + col)
            count += backtrack(row + 1)
            columns.remove(col)
            diagonal1.remove(row - col)
            diagonal2.remove(row + col)
        return count

    columns, diagonal1, diagonal2 = set(), set(), set()
    return backtrack(0)

def total_n_queens(n: int) -> int:
    def is_valid(board):
        current_queen_row, current_queen_col = board[-1]
        for row, col in board[:-1]:
            if col == current_queen_col or \
               row - col == current_queen_row - current_queen_col or \
               row + col == current_queen_row + current_queen_col:
                return False
        return True

    def solve(n, row=0, board=[]):
        if row == n:
            return 1
        count = 0
        for col in range(n):
            board.append((row, col))
            if is_valid(board):
                count += solve(n, row + 1, board)
            board.pop()
        return count

    return solve(n)

