def total_n_queens(n: int) -> int:
    if n < 1:
        return 0
    if n == 1:
        return 1
    solutions = [0 for _ in range(n + 1)]
    solutions[0], solutions[1] = 1, 1
    def backtrack(row, solutions):
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if solutions[col] == 0 and not any(solutions[i] == col + row - i or solutions[i] == col - row + i for i in range(row)):
                solutions[col] = row
                count += backtrack(row + 1, solutions)
                solutions[col] = 0
        return count
    return backtrack(0, solutions)

